sites.find:
vec2f_t displacement = {
    frame_dt * particle->velocity.x,
    frame_dt * particle->velocity.y,
};
vec2f_t previous_position = {
    particle->position.x - displacement.x,
    particle->position.y - displacement.y,
};
vec2f_t hit_direction = {
    previous_position.x
        - creature_pool[hit_id].position.x,
    previous_position.y
        - creature_pool[hit_id].position.y,
};
float hit_angle = (float)atan2(
    hit_direction.y,
    hit_direction.x);

replacements.text:
particle_displacement.x =
    frame_dt * particle->velocity.x;
particle_displacement.y =
    frame_dt * particle->velocity.y;
particle_previous_position.x =
    particle->position.x
        - particle_displacement.x;
particle_previous_position.y =
    particle->position.y
        - particle_displacement.y;
particle_hit_direction.x =
    particle_previous_position.x
        - creature_pool[hit_id].position.x;
particle_hit_direction.y =
    particle_previous_position.y
        - creature_pool[hit_id].position.y;
float hit_angle = (float)atan2(
    particle_hit_direction.y,
    particle_hit_direction.x);
